package com.vandorlabs.neoforge.gear;

import com.vandorlabs.redstone.ChannelList;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.Tag;

/** Immutable Source-compatible choices; ownership and live phase never enter a configured item. */
public record NativeGearSettings(int trigger,int direction,ChannelList channels,boolean legacyAnyChannels,
        boolean pushBlocks,boolean rotatePayload,boolean middleHinge,boolean join,int joinRange,
        boolean carryLoad,int loadHeight,double startAngle,double activeAngle,double activeExtension,int footFacing) {
    public NativeGearSettings {
        if(trigger<0||trigger>2||direction<0||direction>3||channels==null||joinRange<1||joinRange>32||loadHeight<1||loadHeight>32||footFacing<0||footFacing>3
                ||!Double.isFinite(startAngle)||startAngle< -180||startAngle>180||Math.rint(startAngle/15)*15!=startAngle
                ||!Double.isFinite(activeAngle)||activeAngle< -180||activeAngle>180||Math.rint(activeAngle/15)*15!=activeAngle
                ||!Double.isFinite(activeExtension)||activeExtension< -8||activeExtension>8)throw new IllegalArgumentException("Invalid arm settings");
    }
    public static NativeGearSettings defaults(){return new NativeGearSettings(0,0,ChannelList.EMPTY,false,false,false,false,false,32,false,1,0,90,1,2);}
    public NativeGearSettings withFootFacing(int facing){return new NativeGearSettings(trigger,direction,channels,legacyAnyChannels,pushBlocks,rotatePayload,middleHinge,join,joinRange,carryLoad,loadHeight,startAngle,activeAngle,activeExtension,facing);}
    private static int integer(CompoundTag tag,String key,int fallback){return tag.contains(key,Tag.TAG_INT)?tag.getInt(key):fallback;}
    private static double number(CompoundTag tag,String key,double fallback){return tag.contains(key,Tag.TAG_DOUBLE)?tag.getDouble(key):fallback;}
    private static void typed(CompoundTag tag,int type,String...keys){for(String key:keys)if(tag.contains(key)&&!tag.contains(key,type))throw new IllegalArgumentException("Malformed arm setting "+key);}
    public static NativeGearSettings readChoices(CompoundTag tag){typed(tag,Tag.TAG_INT,"Trigger","Direction","JoinRange","LoadHeight","FootFacing");typed(tag,Tag.TAG_STRING,"Channels");typed(tag,Tag.TAG_BYTE,"LegacyAnyChannels","PushBlocks","RotatePayload","MiddleHinge","JoinArms","CarryLoad","Deployed");typed(tag,Tag.TAG_DOUBLE,"StartAngle","ActiveAngle","ActiveExtension");if(tag.getString("Channels").length()>ChannelList.MAX_TEXT_LENGTH)throw new IllegalArgumentException("Arm channel text bound");var channels=ChannelList.parse(tag.getString("Channels"));if(channels==null)throw new IllegalArgumentException("Invalid arm channels");return new NativeGearSettings(integer(tag,"Trigger",0),integer(tag,"Direction",0),channels,tag.getBoolean("LegacyAnyChannels"),tag.getBoolean("PushBlocks"),tag.getBoolean("RotatePayload"),tag.getBoolean("MiddleHinge"),tag.getBoolean("JoinArms"),integer(tag,"JoinRange",32),tag.getBoolean("CarryLoad"),integer(tag,"LoadHeight",1),number(tag,"StartAngle",0),number(tag,"ActiveAngle",90),number(tag,"ActiveExtension",1),integer(tag,"FootFacing",2));}
    public static NativeGearSettings readSaved(CompoundTag tag){typed(tag,Tag.TAG_INT,"GearTrigger","ArmJoinRange","ArmLoadHeight","ArmFootFacing","GearFootFacing");typed(tag,Tag.TAG_STRING,"GearDirection","GearChannels");typed(tag,Tag.TAG_BYTE,"GearLegacyAnyChannels","ArmPushBlocks","ArmRotatePayload","ArmMiddleHinge","ArmJoinEnabled","ArmCarryLoad");typed(tag,Tag.TAG_DOUBLE,"ArmStartAngle","ArmActiveAngle","ArmActiveExtension");var choices=new CompoundTag();choices.putInt("Trigger",integer(tag,"GearTrigger",0));String name=tag.getString("GearDirection");int direction=0;if(!name.isEmpty())try{direction=com.vandorlabs.gear.core.GearMotion.Direction.valueOf(name).ordinal();}catch(IllegalArgumentException invalid){throw new IllegalArgumentException("Unknown arm direction",invalid);}choices.putInt("Direction",direction);choices.putString("Channels",tag.getString("GearChannels"));choices.putBoolean("LegacyAnyChannels",tag.getBoolean("GearLegacyAnyChannels"));choices.putBoolean("PushBlocks",tag.getBoolean("ArmPushBlocks"));choices.putBoolean("RotatePayload",tag.getBoolean("ArmRotatePayload"));choices.putBoolean("MiddleHinge",tag.getBoolean("ArmMiddleHinge"));choices.putBoolean("JoinArms",tag.getBoolean("ArmJoinEnabled"));choices.putInt("JoinRange",integer(tag,"ArmJoinRange",32));choices.putBoolean("CarryLoad",tag.getBoolean("ArmCarryLoad"));choices.putInt("LoadHeight",integer(tag,"ArmLoadHeight",1));choices.putDouble("StartAngle",number(tag,"ArmStartAngle",0));choices.putDouble("ActiveAngle",number(tag,"ArmActiveAngle",90));choices.putDouble("ActiveExtension",number(tag,"ArmActiveExtension",1));choices.putInt("FootFacing",integer(tag,"ArmFootFacing",integer(tag,"GearFootFacing",2)));return readChoices(choices);}
    public CompoundTag choices(){var tag=new CompoundTag();tag.putInt("Trigger",trigger);tag.putInt("Direction",direction);tag.putString("Channels",channels.toString());tag.putBoolean("LegacyAnyChannels",legacyAnyChannels);tag.putBoolean("PushBlocks",pushBlocks);tag.putBoolean("RotatePayload",rotatePayload);tag.putBoolean("MiddleHinge",middleHinge);tag.putBoolean("JoinArms",join);tag.putInt("JoinRange",joinRange);tag.putBoolean("CarryLoad",carryLoad);tag.putInt("LoadHeight",loadHeight);tag.putDouble("StartAngle",startAngle);tag.putDouble("ActiveAngle",activeAngle);tag.putDouble("ActiveExtension",activeExtension);tag.putInt("FootFacing",footFacing);return tag;}
    public void writeSaved(CompoundTag tag){tag.putInt("GearTrigger",trigger);tag.putString("GearDirection",com.vandorlabs.gear.core.GearMotion.Direction.values()[direction].name());tag.putString("GearChannels",channels.toString());tag.putBoolean("GearLegacyAnyChannels",legacyAnyChannels);tag.putBoolean("ArmPushBlocks",pushBlocks);tag.putBoolean("ArmRotatePayload",rotatePayload);tag.putBoolean("ArmMiddleHinge",middleHinge);tag.putBoolean("ArmJoinEnabled",join);tag.putInt("ArmJoinRange",joinRange);tag.putBoolean("ArmCarryLoad",carryLoad);tag.putInt("ArmLoadHeight",loadHeight);tag.putDouble("ArmStartAngle",startAngle);tag.putDouble("ArmActiveAngle",activeAngle);tag.putDouble("ArmActiveExtension",activeExtension);tag.putInt("ArmFootFacing",footFacing);}
}
